=== sample event: order-updated.tsp ===
import "./_base.tsp";

namespace TemplateContracts;

@doc("Published by the Go sync worker after a successful Order canonical UPSERT. TS Sales consumes for cache invalidation; Catalog for ProductCost reconciliation; Notifications for the per-Store order-push opt-in flow.")
model OrderUpdatedEvent extends IntegrationEvent {
  name: "integration.shared.order.updated";

  @doc("Provider platform the order originated on (drives platform-specific reconciliation paths). Mirrored from entity for index-friendly consumer lookups.")
  platform: SalesPlatform;

  @doc("Provider's native order id. Combined with platform gives the deterministic UUIDv5 stored in `entityId`. Mirrored from entity.")
  externalId: string;

  @doc("Provider's StoreIntegration externalId (e.g. shop domain for Shopify). Used to resolve the tenant the order belongs to. Mirrored from entity.")
  storeIntegrationExternalId: string;

  @doc("Canonical payment status BK Dash derived from the provider's native status. Mirrored from entity.")
  paymentStatus: PaymentStatus;

  @doc("Total amount in cents. Sign is positive for sales, negative if the provider reported a net refund > sale. Mirrored from entity.")
  totalCents: int64;

  @doc("ISO-4217 currency of `totalCents`. Mirrored from entity.")
  currency: CurrencyCode;

  @doc("True the FIRST time this (platform, externalId) was ever written by go-worker. Distinguishes create vs subsequent update at the consumer.")
  isNew: boolean;

  @doc("Provider's cart token (matches `externalCartId` on the cart projection). Drives the symmetric cart→order link when the order arrives AFTER the pixel CHECKOUT_COMPLETED. Null when the provider doesn't attach a cart token (manual orders, draft orders, providers without a checkout-pixel pipeline). Mirrored from entity.")
  cartToken?: string;

  @doc("Full Order snapshot at publish time (SPEC-14). Shape: `{ id, storeId, storeIntegrationId, storeIntegrationExternalId, platform, externalId, paymentStatus, totalCents, currency, cartToken? }`.")
  entity: unknown;
}

=== sample event: order-overridden.tsp (intra-API?) ===
import "./_base.tsp";

namespace TemplateContracts;

@doc("Published by TS Sales after a merchant updates an OrderOverride (the patch aggregate that holds merchant-corrected fields on top of the Go-owned canonical Order). Analytics consumes for cache invalidation; downstream profit-margin recomputation triggers off the entity snapshot.")
model OrderOverriddenEvent extends IntegrationEvent {
  name: "integration.shared.order.overridden";

  @doc("Canonical Order id (UUIDv5 from SHOPIFY:<externalId>, etc.). Joins `sales.orders.id`. Mirrored from entity for index-friendly consumer lookups.")
  orderId: string;

  @doc("Provider's StoreIntegration externalId — the second half of the composite key on `order_overrides`. Required because overrides are scoped per integration: editing the override on one StoreIntegration must NOT bleed into a reconnected one with the same external_id. Mirrored from entity.")
  storeIntegrationExternalId: string;

  @doc("Full OrderOverride snapshot at publish time. Shape: `{ orderId, storeIntegrationExternalId, storeId, fields: { paymentMethod?, paymentStatus?, revenueCents?, shippingCents?, feesCents?, taxesCents?, productCostByLine? } }`. SPEC-14: consumers read fields directly instead of correlating against a `changedFields` delta.")
  entity: unknown;
}

