import { injectable } from 'tsyringe-neo'
import { EventHandler, ExternalMediator, DrizzleClient } from '@bk-dash/core-typescript'
import { and, eq, isNull } from 'drizzle-orm'
import { OrderUpdatedEvent, CartLinkedToOrderEvent } from '@bk-dash/contracts-typescript/wire/events'
import { carts, orders } from '@bk-dash/contracts/db'

type CartLinkResult = { linked: false } | { linked: true; cartId: string; orderId: string; orderExternalId: string }

/**
 * External handler subscribing to Go-published
 * `integration.shared.order.updated`. Symmetric to
 * `PixelCheckoutCompletedLinkCartHandler` for the case where the order
 * arrives AFTER the pixel CHECKOUT_COMPLETED.
 *
 * Drops events without a cartToken (manual / draft orders, providers
 * without a checkout-pixel pipeline). Otherwise the same atomic
 * `linkToOrder` two-step — idempotent across both directions.
 *
 * Cart link is now inline Drizzle (SPEC-10 — CartProjectionRepository removed).
 */
@injectable()
export class OrderUpdatedLinkCartHandler extends EventHandler<typeof OrderUpdatedEvent> {
	readonly event = OrderUpdatedEvent

	constructor(
		private readonly db: DrizzleClient,
		private readonly externalMediator: ExternalMediator,
	) {
		super()
	}

	async handle(event: this['input']): Promise<void> {
		const cartToken = event.payload.cartToken
		if (!cartToken) return

		const result = await this.linkToOrder(event.payload.platform, cartToken)
		if (!result.linked) return

		await this.externalMediator.publish(
			new CartLinkedToOrderEvent({
				ownerId: event.ownerId ?? '',
				payload: {
					platform: event.payload.platform,
					cartExternalId: cartToken,
					orderExternalId: result.orderExternalId,
					storeIntegrationExternalId: event.payload.storeIntegrationExternalId,
				},
			}),
		)
	}

	private async linkToOrder(platform: string, externalCartId: string): Promise<CartLinkResult> {
		const orderRows = await this.db
			.select({ id: orders.id, externalId: orders.externalId })
			.from(orders)
			.where(and(eq(orders.platform, platform), eq(orders.cartToken, externalCartId)))
			.limit(1)
		const order = (orderRows as Array<{ id: string; externalId: string }>)[0]
		if (!order) return { linked: false }

		const updated = await this.db
			.update(carts)
			.set({ linkedOrderId: order.id })
			.where(and(eq(carts.platform, platform), eq(carts.externalCartId, externalCartId), isNull(carts.linkedOrderId)))
			.returning({ cartId: carts.id })
		const row = (updated as Array<{ cartId: string }>)[0]
		if (!row) return { linked: false }

		return { linked: true, cartId: row.cartId, orderId: order.id, orderExternalId: order.externalId }
	}
}

import { injectable } from 'tsyringe-neo'
import { EventHandler, ExternalMediator } from '@bk-dash/core-typescript'
import { OrderOverriddenEvent as OrderOverriddenIntegrationEvent } from '@bk-dash/contracts-typescript/wire/events'
import { OrderOverriddenEvent } from '../events'
import { OrderOverrideRepository } from '../repositories/OrderOverrideRepository'

/**
 * Bridges the in-process `sales.order.overridden` domain event to the
 * cross-BC `integration.shared.order.overridden` integration event so
 * Analytics can scope cache invalidation.
 *
 * SPEC-14: the wire event carries the full OrderOverride snapshot under
 * `entity` instead of a `changedFields` delta. We rehydrate the entity
 * via the repository (the domain event only carries identifiers + the
 * delta list, not the full snapshot).
 */
@injectable()
export class OrderOverriddenIntegrationPublisherHandler extends EventHandler<typeof OrderOverriddenEvent> {
	readonly event = OrderOverriddenEvent

	constructor(
		private readonly mediator: ExternalMediator,
		private readonly overrideRepo: OrderOverrideRepository,
	) {
		super()
	}

	async handle(event: this['input']): Promise<void> {
		// ownerId is set by the use case from entity.storeId so it's always
		// present in practice — `?? ''` is defensive for the framework's
		// `ownerId?: string` type.
		const ownerId = event.ownerId ?? event.payload.storeId ?? ''
		const override = await this.overrideRepo.findByPin(event.payload.orderId, event.payload.storeIntegrationExternalId)
		const entity =
			override === undefined
				? {
						orderId: event.payload.orderId,
						storeIntegrationExternalId: event.payload.storeIntegrationExternalId,
						storeId: event.payload.storeId,
					}
				: {
						orderId: override.orderId,
						storeIntegrationExternalId: override.storeIntegrationExternalId,
						storeId: override.storeId,
						fields: override.fields,
					}
		await this.mediator.publish(
			new OrderOverriddenIntegrationEvent({
				ownerId,
				payload: {
					orderId: event.payload.orderId,
					storeIntegrationExternalId: event.payload.storeIntegrationExternalId,
					entity,
				},
			}),
		)
	}
}

import { injectable } from 'tsyringe-neo'
import { EventHandler, ExternalMediator } from '@bk-dash/core-typescript'
import { SubscriptionQuotaUpdatedEvent } from '@bk-dash/contracts-typescript/wire/events'
import type { PlanTier } from '@bk-dash/contracts-typescript/wire/enums'
import { SubscriptionCancelledEvent, SubscriptionCreatedEvent, SubscriptionOverdueEvent, SubscriptionPausedEvent } from '../events'

/**
 * Internal-to-billing handlers that bridge state-change domain events to the
 * `integration.shared.subscription.quota_updated` integration event the
 * Tenancy BC consumes for quota-cache invalidation.
 *
 * Wired for the 4 events that change effective quota: Created (newly
 * active), Cancelled + Paused + Overdue (active rights revoked). Paid and
 * Renewed don't change effective quota — same tier remains active, no
 * publish.
 *
 * One handler class per event because EventHandler.name binds to
 * `this.event.name` for framework auto-registration — the mediator allows
 * multiple handlers per event name, but a single class can only declare one
 * `event` field.
 */

async function publish(mediator: ExternalMediator, userId: string, tier: PlanTier): Promise<void> {
	await mediator.publish(
		new SubscriptionQuotaUpdatedEvent({
			ownerId: userId,
			payload: { userId, tier },
		}),
	)
}

/** Newly active subscription → quota refresh. */
@injectable()
export class SubscriptionCreatedQuotaUpdatedHandler extends EventHandler<typeof SubscriptionCreatedEvent> {
	readonly event = SubscriptionCreatedEvent

	constructor(private readonly mediator: ExternalMediator) {
		super()
	}

	async handle(event: this['input']): Promise<void> {
		await publish(this.mediator, event.payload.userId, event.payload.tier)
	}
}

/** Cancellation → quota downgrade. */
@injectable()
export class SubscriptionCancelledQuotaUpdatedHandler extends EventHandler<typeof SubscriptionCancelledEvent> {
	readonly event = SubscriptionCancelledEvent

	constructor(private readonly mediator: ExternalMediator) {
		super()
	}

	async handle(event: this['input']): Promise<void> {
		// SubscriptionCancelledEvent's payload doesn't carry userId (lean spec);
		// the canonical actor is on event.ownerId (mapper sets it from
		// existing.userId when the cancellation is mapped). Defensive '' fallback.
		const userId = event.ownerId ?? ''
		await publish(this.mediator, userId, event.payload.tier)
	}
}

/** Pause → quota effectively reduced (active row but no service rights). */
@injectable()
export class SubscriptionPausedQuotaUpdatedHandler extends EventHandler<typeof SubscriptionPausedEvent> {
	readonly event = SubscriptionPausedEvent

	constructor(private readonly mediator: ExternalMediator) {
		super()
	}

	async handle(event: this['input']): Promise<void> {
		const userId = event.ownerId ?? ''
		await publish(this.mediator, userId, event.payload.tier)
	}
}

/** Overdue → quota effectively reduced (payment late, active rights revoked). */
@injectable()
export class SubscriptionOverdueQuotaUpdatedHandler extends EventHandler<typeof SubscriptionOverdueEvent> {
	readonly event = SubscriptionOverdueEvent

	constructor(private readonly mediator: ExternalMediator) {
		super()
	}

	async handle(event: this['input']): Promise<void> {
		const userId = event.ownerId ?? ''
		await publish(this.mediator, userId, event.payload.tier)
	}
}

