import { injectable } from 'tsyringe-neo'
import { EventHandler, ExternalMediator } from '@bk-dash/core-typescript'
import { CampaignProductBindingCreatedEvent as CampaignProductBindingCreatedIntegrationEvent } from '@bk-dash/contracts-typescript/wire/events'
import { CampaignProductBindingCreatedEvent } from '../events'

/**
 * Bridges the in-process `marketing.campaign_product_binding.created` event
 * to `integration.shared.marketing.campaign_product_binding_created` so
 * Analytics can recompute ROAS attributions.
 */
@injectable()
export class CampaignProductBindingCreatedHandler extends EventHandler<typeof CampaignProductBindingCreatedEvent> {
	readonly event = CampaignProductBindingCreatedEvent

	constructor(private readonly mediator: ExternalMediator) {
		super()
	}

	async handle(event: this['input']): Promise<void> {
		const ownerId = event.ownerId ?? event.payload.storeId
		await this.mediator.publish(
			new CampaignProductBindingCreatedIntegrationEvent({
				ownerId,
				payload: {
					storeId: event.payload.storeId,
					campaignId: event.payload.campaignId,
					productIds: event.payload.productIds,
					variantIds: event.payload.variantIds,
				},
			}),
		)
	}
}

