import { injectable } from 'tsyringe-neo'
import { EventHandler, Id, type Transaction } from '@bk-dash/core-typescript'
import { OrderUpdatedEvent } from '@bk-dash/contracts-typescript/wire/events'
import { ProductCostSolver } from '../../services/ProductCostSolver'
import { ProductCostLineAllocator } from '../../services/ProductCostLineAllocator'
import { ProductCostQueryService } from '../../../catalog/services/ProductCostQueryService'
import { OrderOverride } from '../../entities/OrderOverride'
import { OrderOverrideRepository } from '../../repositories/OrderOverrideRepository/OrderOverrideRepository'
import { OrderQueryService, type OrderLineDTO } from '../../services/OrderQueryService'

type OrderQueryResult = Awaited<ReturnType<OrderQueryService['findById']>>

@injectable()
export class ProductCostApplicationHandler extends EventHandler<typeof OrderUpdatedEvent> {
	readonly event = OrderUpdatedEvent
	private readonly allocator = new ProductCostLineAllocator()

	constructor(
		private readonly orderQuery: OrderQueryService,
		private readonly costQuery: ProductCostQueryService,
		private readonly overrideRepo: OrderOverrideRepository,
	) {
		super()
	}

	async handle(event: this['input'], tx?: Transaction): Promise<void> {
		const { platform, externalId } = event.payload
		const orderId = Id.fromSeed('order', platform, externalId).value
		const order = await this.orderQuery.findById(orderId)
		if (!order) return
		await this.applyForOrder(order, tx)
	}

	private async applyForOrder(order: NonNullable<OrderQueryResult>, tx?: Transaction): Promise<void> {
		const lines: OrderLineDTO[] = order.lines
		if (lines.length === 0) return

		const variantProducts = new Map<string, string>()
		const variantQuantities = new Map<string, number>()
		const guardedLines: Array<{ id: string; productId: string; variantId: string; quantity: number }> = []
		for (const line of lines) {
			if (!line.variantId || !line.productId) continue
			variantProducts.set(line.variantId, line.productId)
			variantQuantities.set(line.variantId, (variantQuantities.get(line.variantId) ?? 0) + line.quantity)
			guardedLines.push({ id: line.id, productId: line.productId, variantId: line.variantId, quantity: line.quantity })
		}
		if (variantQuantities.size === 0) return

		const productIds = Array.from(new Set(variantProducts.values()))
		const costs = await this.costQuery.findApplicable({ storeId: order.storeId, productIds, at: order.externalCreatedAt })

		const solved = new ProductCostSolver({ costs, variantProducts, variants: variantQuantities }).solve()
		const productCostByLine = this.allocator.allocate(
			solved,
			guardedLines.map(l => ({ id: l.id, productId: l.productId, quantity: l.quantity })),
		)

		let override = await this.overrideRepo.findByPin(order.id, order.storeIntegrationExternalId, tx)
		if (!override) {
			override = OrderOverride.create({
				storeId: order.storeId,
				orderId: order.id,
				storeIntegrationExternalId: order.storeIntegrationExternalId,
				fields: {},
			})
		}
		override.setProductCostByLine(productCostByLine)
		await this.overrideRepo.save(override, tx)
	}
}

import { injectable } from 'tsyringe-neo'
import { EventHandler, ExternalMediator } from '@bk-dash/core-typescript'
import { StoreMemberInvitedEvent as StoreMemberInvitedIntegrationEvent } from '@bk-dash/contracts-typescript/wire/events'
import { StoreMemberInvitedEvent } from '../events'
import { StoreInvitationRepository } from '../repositories/StoreInvitationRepository'

/**
 * Bridges the in-process `tenancy.store_member.invited` domain event to the
 * cross-service `integration.shared.store.member_invited` integration event.
 * The Notifications BC consumes the integration event and sends the invite email.
 *
 * Looks up the StoreInvitation to source `expiresAt` (not on the domain event
 * payload — kept lean to avoid leaking entity columns into the event schema).
 */
@injectable()
export class StoreMemberInvitedHandler extends EventHandler<typeof StoreMemberInvitedEvent> {
	readonly event = StoreMemberInvitedEvent

	constructor(
		private readonly invitations: StoreInvitationRepository,
		private readonly externalMediator: ExternalMediator,
	) {
		super()
	}

	async handle(event: this['input']): Promise<this['output']> {
		const invitation = await this.invitations.findById(event.payload.storeInvitationId)
		// Graceful exit if the invitation row vanished between issuance and dispatch
		// (e.g., manual purge). Better to drop the email than crash the handler chain.
		if (!invitation) return

		// StoreMemberInvitedEvent is always constructed with ownerId = inviter userId
		// by InviteMember use case — domain event's ownerId became optional in the
		// framework change (some events have no actor), but this one always has it.
		const inviterId = event.ownerId ?? ''

		await this.externalMediator.publish(
			new StoreMemberInvitedIntegrationEvent({
				ownerId: inviterId,
				payload: {
					storeId: event.payload.storeId,
					email: event.payload.email,
					role: event.payload.role,
					token: event.payload.invitationToken,
					expiresAt: invitation.expiresAt,
					invitedByUserId: inviterId,
				},
			}),
		)
	}
}

