import { injectable } from 'tsyringe-neo'
import { EventHandler } from '@bk-dash/core-typescript'
import { OrderUpdatedEvent } from '@bk-dash/contracts-typescript/wire/events'
import { NotificationCategory } from '@bk-dash/contracts-typescript/wire/enums'
import { StoreIntegrationRepository } from '../../integration/repositories/StoreIntegrationRepository'
import { StoreMembershipRepository } from '../../tenancy/repositories/StoreMembershipRepository'
import { SendNotification } from '../usecases/SendNotification'

/**
 * External handler subscribing to the Go-published
 * `integration.shared.order.updated` event. Fans out an
 * ORDER_RECEIVED push to every member of the store the first time
 * this `(platform, externalId)` is seen (`isNew=true`). Subsequent
 * status updates (paid → refunded → etc.) don't re-push.
 *
 * Resolves recipients via Integration's `findByPlatformAndExternalId`
 * (storeIntegrationExternalId → storeId) + Tenancy's `findByStoreId`
 * (storeId → memberships). Drops silently when the integration or
 * its store has no members.
 *
 * Store-level opt-in toggle is a future iter; for now every member
 * receives the push.
 */
@injectable()
export class OrderUpdatedNotifyHandler extends EventHandler<typeof OrderUpdatedEvent> {
	readonly event = OrderUpdatedEvent

	constructor(
		private readonly storeIntegrationRepo: StoreIntegrationRepository,
		private readonly memberships: StoreMembershipRepository,
		private readonly sendNotification: SendNotification,
	) {
		super()
	}

	async handle(event: this['input']): Promise<void> {
		if (!event.payload.isNew) return

		const integration = await this.storeIntegrationRepo.findByPlatformAndExternalId(
			event.payload.platform,
			event.payload.storeIntegrationExternalId,
		)
		if (integration === undefined) return

		const members = await this.memberships.findByStoreId(integration.storeId.value)
		const targetUserIds = members.map(m => m.userId.value)
		if (targetUserIds.length === 0) return

		const amount = (event.payload.totalCents / 100).toFixed(2)
		await this.sendNotification.execute({
			userId: integration.ownerId.value,
			storeId: integration.storeId.value,
			targetUserIds,
			title: `New order: ${amount} ${event.payload.currency}`,
			content: `Order ${event.payload.externalId} (${event.payload.paymentStatus})`,
			category: NotificationCategory.ORDER_RECEIVED,
			important: false,
			pushEnabled: true,
			emailEnabled: false,
			contentType: 'text/plain',
			payload: {
				platform: event.payload.platform,
				orderExternalId: event.payload.externalId,
				storeIntegrationExternalId: event.payload.storeIntegrationExternalId,
				totalCents: event.payload.totalCents,
				currency: event.payload.currency,
				paymentStatus: event.payload.paymentStatus,
			},
		})
	}
}

import { injectable } from 'tsyringe-neo'
import { EventHandler } from '@bk-dash/core-typescript'
import { IntegrationHandshakeFailedEvent } from '@bk-dash/contracts-typescript/wire/events'
import { NotificationCategory } from '@bk-dash/contracts-typescript/wire/enums'
import { StoreIntegrationRepository } from '../../integration/repositories/StoreIntegrationRepository'
import { SendNotification } from '../usecases/SendNotification'

/**
 * External handler subscribing to the Go-published
 * `integration.shared.integration.handshake_failed` event. Fans out a
 * push notification to the StoreIntegration owner so the merchant
 * sees the disconnect prompt without opening the dashboard.
 *
 * Resolves the recipient via Integration BC's
 * `findByPlatformAndExternalId` — Integration owns the StoreIntegration
 * row + its `ownerId`. Drops silently when the row is missing (delete
 * race / cross-tenant leakage guard).
 */
@injectable()
export class IntegrationHandshakeFailedNotifyHandler extends EventHandler<typeof IntegrationHandshakeFailedEvent> {
	readonly event = IntegrationHandshakeFailedEvent

	constructor(
		private readonly storeIntegrationRepo: StoreIntegrationRepository,
		private readonly sendNotification: SendNotification,
	) {
		super()
	}

	async handle(event: this['input']): Promise<void> {
		const integration = await this.storeIntegrationRepo.findByPlatformAndExternalId(
			event.payload.platform,
			event.payload.providerExternalId,
		)
		if (integration === undefined) return

		await this.sendNotification.execute({
			userId: integration.ownerId.value,
			storeId: integration.storeId.value,
			targetUserIds: [integration.ownerId.value],
			title: `${event.payload.platform} integration disconnected`,
			content: event.payload.errorMessage,
			category: NotificationCategory.INTEGRATION_DISCONNECTED,
			important: true,
			pushEnabled: true,
			emailEnabled: false,
			contentType: 'text/plain',
			payload: {
				platform: event.payload.platform,
				providerExternalId: event.payload.providerExternalId,
				storeIntegrationId: integration.id.value,
				errorCode: event.payload.errorCode,
				attemptedAt: event.payload.attemptedAt,
			},
		})
	}
}

